package ru.main.explorer;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.*;

/** Local diagnostics only. Nothing is uploaded. */
final class CrashReport {
 private static boolean installed;
 static synchronized void install(Context context){if(installed)return;installed=true;File file=new File(context.getFilesDir(),"last-crash.txt");Thread.UncaughtExceptionHandler previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((thread,error)->{try(FileOutputStream raw=new FileOutputStream(file)){OutputStream bounded=new FilterOutputStream(raw){int bytes;public void write(int b)throws IOException{if(bytes++<65536)out.write(b);}public void write(byte[] b,int off,int len)throws IOException{int available=Math.min(len,Math.max(0,65536-bytes));if(available>0){out.write(b,off,available);bytes+=available;}}};PrintWriter writer=new PrintWriter(new OutputStreamWriter(bounded,"UTF-8"));writer.println("MapNotes "+Language.version(context)+" · "+Language.date(context,System.currentTimeMillis())+" · "+thread.getName());error.printStackTrace(writer);writer.flush();}catch(Throwable ignored){}if(previous!=null)previous.uncaughtException(thread,error);else android.os.Process.killProcess(android.os.Process.myPid());});}
 static String read(Context context){Language.initialize(context);StringBuilder report=new StringBuilder();if(Build.VERSION.SDK_INT>=30)try{ActivityManager manager=(ActivityManager)context.getSystemService(Context.ACTIVITY_SERVICE);List<ApplicationExitInfo> exits=manager.getHistoricalProcessExitReasons(context.getPackageName(),0,1);for(ApplicationExitInfo exit:exits)report.append(Messages.text("last_exit")).append(Language.date(context,exit.getTimestamp())).append(Messages.text("nandroid_reason")).append(reason(exit.getReason())).append("\n").append(exit.getDescription()).append("\n\n");}catch(Exception ignored){}File file=new File(context.getFilesDir(),"last-crash.txt");if(file.exists())try{report.append(new String(MapPack.read(file,65536),"UTF-8"));}catch(Exception ignored){}return report.length()==0?Messages.text("no_crash_report_has_been_recorded_yet"):report.toString();}
 static String reason(int reason){switch(reason){case ApplicationExitInfo.REASON_ANR:return Messages.text("app_not_responding_anr");case ApplicationExitInfo.REASON_LOW_MEMORY:return Messages.text("out_of_memory");case ApplicationExitInfo.REASON_CRASH:return Messages.text("java_crash");case ApplicationExitInfo.REASON_CRASH_NATIVE:return Messages.text("native_code_crash");case 16:return Messages.text("stopped_during_app_update");case ApplicationExitInfo.REASON_USER_REQUESTED:return Messages.text("stopped_by_user_or_update");default:return Messages.text("code")+reason;}}
 static void show(Activity activity){String report=read(activity);new AlertDialog.Builder(activity).setTitle(Messages.text("crash_report")).setMessage(report).setPositiveButton(Messages.text("copy"),(d,w)->{ClipboardManager clipboard=(ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("MapNotes",report));}).setNegativeButton(Messages.text("close"),null).show();}
}
